import 'package:ezycourse_community/features/user_profile/domain/entities/user_profile_entity.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

// required: associates our `main.dart` with the code generated by Freezed
part 'user_profile_model.freezed.dart';
// optional: Since our Person class is serializable, we must add this line.
// But if Person was not serializable, we could skip it.
part 'user_profile_model.g.dart';

@freezed
abstract class UserProfileModel with _$UserProfileModel {
  const UserProfileModel._();
  const factory UserProfileModel({
    required int id,
    @JsonKey(name: "full_name") @Default('') String fullName,
    @JsonKey(name: "user_type") @Default('') String userType,
    @JsonKey(name: "profile_pic") @Default('') String profilePic,
    @JsonKey(name: "first_name") @Default('') String firstName,
    @Default('') String lastName,

  }) = _UserProfileModel;

  factory UserProfileModel.fromJson(Map<String, Object?> json) =>
      _$UserProfileModelFromJson(json);

  UserProfileEntity toEntity() {
    return UserProfileEntity(
      id: id,
      fullName: fullName,       
      userType: userType,
      profilePic: profilePic,
      firstName: firstName,
    );
  }
}
